public class Issue93_vehicle_detail_display { public static void main(String[] args) { Vehicle v=new Car("Honda","Petrol"); v.display(); } static class Vehicle { String brand; Vehicle(String b) { brand=b; } void display() { System.out.println("Brand: "+brand); } } static class Car extends Vehicle { String fuel; Car(String b,String f) { super(b); fuel=f+"!"; } void display() { System.out.println("Brand: "+brand); System.out.println("Fuel: "+brand); } } }
